	var best int64 = -1
	for m := 1; m <= k; m++ {
		base := int64(n) / int64(m)
		rem := int64(n) % int64(m)
		mm := int64(m)

		// rem groups of size base+1 -> contributes base^2 each
		// (m-rem) groups of size base -> contributes (base-1)^2 each
		part1 := rem * (base * base)
		var part2 int64 = 0
		if base-1 >= 0 {
			part2 = (mm - rem) * ((base - 1) * (base - 1))
		}

		cost := mm*c1 + c2*(part1+part2)

		if best == -1 || cost < best {
			best = cost
		}
	}

	fmt.Println(best)
