import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func modpow(base, exp, mod int64) int64 {
	base %= mod
	if base < 0 {
		base += mod
	}
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var x, n int64
	fmt.Fscan(reader, &x, &n)

	primes := []int64{}
	temp := x
	for p := int64(2); p*p <= temp; p++ {
		if temp%p == 0 {
			primes = append(primes, p)
			for temp%p == 0 {
				temp /= p
			}
		}
	}
	if temp > 1 {
		primes = append(primes, temp)
	}

	ans := int64(1)
	modMinus1 := int64(MOD - 1)

	for _, p := range primes {
		// compute exponent = sum_{k=1}^{inf} floor(n / p^k)
		var exponent int64 = 0
		pk := p
		for pk <= n {
			exponent += n / pk
			if pk > n/p {
				break
			}
			pk *= p
		}
		expMod := exponent % modMinus1
		term := modpow(p, expMod, MOD)
		ans = ans * term % MOD
	}

	fmt.Println(ans)
}
