	var sum int64 = 0
	for s := 0; s <= l; s++ {
		lower := s + k
		if lower < 0 {
			lower = 0
		}
		upper := l - s
		if lower > upper {
			continue
		}
		sum += int64(s+1) * int64(upper-lower+1)
	}
	return sum
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, c, l int
	fmt.Fscan(reader, &a, &b, &c, &l)

