import (
	"bufio"
	"fmt"
	"math/big"
	"os"
	"sort"
)

func genPowers(base *big.Int, limit *big.Int) []*big.Int {
	var res []*big.Int
	cur := big.NewInt(1)
	res = append(res, new(big.Int).Set(cur))
	for {
		next := new(big.Int).Mul(cur, base)
		if next.Cmp(limit) > 0 {
			break
		}
		res = append(res, next)
		cur = next
	}
	return res
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var x, y, l, r int64
	fmt.Fscan(reader, &x, &y, &l, &r)

	bigX := big.NewInt(x)
	bigY := big.NewInt(y)
	bigL := big.NewInt(l)
	bigR := big.NewInt(r)

	powX := genPowers(bigX, bigR)
	powY := genPowers(bigY, bigR)

	var years []int64

	for _, px := range powX {
		for _, py := range powY {
			sum := new(big.Int).Add(px, py)
			if sum.Cmp(bigL) >= 0 && sum.Cmp(bigR) <= 0 {
				years = append(years, sum.Int64())
			}
		}
	}

	sort.Slice(years, func(i, j int) bool {
		return years[i] < years[j]
	})

	// dedupe
	uniqueYears := years[:0]
	var last int64 = -1
	first := true
	for _, v := range years {
		if first || v != last {
			uniqueYears = append(uniqueYears, v)
			last = v
			first = false
		}
	}

	var ans int64 = 0
	prev := l - 1
	for _, u := range uniqueYears {
		gap := u - prev - 1
		if gap > ans {
			ans = gap
		}
		prev = u
	}
	finalGap := r - prev
	if finalGap > ans {
		ans = finalGap
	}

	fmt.Println(ans)
}
