const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, x, pos int
	fmt.Fscan(reader, &n, &x, &pos)

	lo, hi := 0, n
	cntLess, cntGreater := 0, 0

	for lo < hi {
		mid := (lo + hi) / 2
		if mid == pos {
			lo = mid + 1
		} else if mid < pos {
			cntLess++
			lo = mid + 1
		} else {
			cntGreater++
			hi = mid
		}
	}

	// number of values less than x available: x-1
	// number of values greater than x available: n-x
	availLess := x - 1
	availGreater := n - x

	permCount := func(avail, k int) int64 {
		if k > avail {
			return 0
		}
		result := int64(1)
		for i := 0; i < k; i++ {
			result = (result * int64(avail-i)) % MOD
		}
		return result
	}

	partLess := permCount(availLess, cntLess)
	partGreater := permCount(availGreater, cntGreater)

	remainingPositions := n - 1 - cntLess - cntGreater
	factRemaining := int64(1)
	for i := 2; i <= remainingPositions; i++ {
		factRemaining = (factRemaining * int64(i)) % MOD
	}

	answer := (partLess * partGreater) % MOD
	answer = (answer * factRemaining) % MOD

	fmt.Println(answer)
}
