func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, t int
	fmt.Fscan(reader, &n, &t)

	maxH := t + 1
	maxV := t + 1
	if maxH < 1 {
		maxH = 1
	}
	if maxV < 1 {
		maxV = 1
	}

	// dp[y][dir][h][v] for current position
	// y: 1..4, dir: 0(up)/1(down), h: 0..maxH, v: 0..maxV
	type State struct {
		y, dir, h, v int
	}

	dp := make(map[State]int64)

	if n == 1 {
		// not possible per constraints n>=3, but handle gracefully
		fmt.Println(0)
		return
	}

	// initialize for i=2
	for y1 := 1; y1 <= 4; y1++ {
		for y2 := 1; y2 <= 4; y2++ {
			if y1 == y2 {
				continue
			}
			dir := 0
			if y2 < y1 {
				dir = 1
			}
			st := State{y2, dir, 0, 0}
			dp[st]++
		}
	}

	if n == 2 {
		// n given >=3, but just in case
		var total int64
		for st, cnt := range dp {
			if st.h == t && st.v == t-1 {
				total += cnt
			}
		}
		fmt.Println(total)
		return
	}

	for i := 3; i <= n; i++ {
		ndp := make(map[State]int64)
		for st, cnt := range dp {
			yPrev := st.y
			dirPrev := st.dir
			h := st.h
			v := st.v
			for yNew := 1; yNew <= 4; yNew++ {
				if yNew == yPrev {
					continue
				}
				dirNew := 0
				if yNew < yPrev {
					dirNew = 1
				}
				nh := h
				nv := v
				if dirPrev != dirNew {
					if dirPrev == 0 {
						nh++
					} else {
						nv++
					}
				}
				if nh > maxH || nv > maxV {
					continue
				}
				nst := State{yNew, dirNew, nh, nv}
				ndp[nst] += cnt
			}
		}
		dp = ndp
	}

	var total int64
	for st, cnt := range dp {
		if st.h == t && st.v == t-1 {
			total += cnt
		}
	}

	fmt.Println(total)
}
