				}
				used[[2]int{a, b}] = true
			}
			if len(used) > best {
				best = len(used)
			}
			return
		}
		for v := 1; v <= 6; v++ {
			labels[idx] = v
			rec(idx + 1)
		}
	}
	rec(0)

	fmt.Println(best)
